const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id;
const r=($input.first()||{}).json||{};
const f=r.fields||r;
const clientIds=Array.isArray(f['Client'])?f['Client']:[];
const D={launchId:r.id||'', clientId:clientIds[0]||'', tableId:String(f['Table ID']||'').trim(), view:String(f['View']||'').trim(), target:String(f['Target']||'').trim(), dedupe:String(f['Dedupe Mode']||'Strict').trim()||'Strict', ws:'', crBase:'', clientName:'', tableName:'', campName:'', receiptName:'', errors:[], warnings:[], counters:[], uploadedNew:0, deployed:0, missing:0, rowsTotal:0, rows:{}, emailToRow:{}, inCamp:{}, skipCounts:{}, rbFailed:false, abort:null, startedAt:Date.now(), runAt:$now.toISO()};
if(!D.launchId){ D.abort='launch row not found'; D.errors.push('launch row not found (recordId missing or invalid)'); }
if(!D.abort&&!D.clientId){ D.abort='no client link'; D.errors.push('launch row has no Client link'); }
if(!D.abort&&!D.tableId){ D.abort='no Table ID'; D.errors.push('launch row has no Table ID'); }
if(!D.abort&&!D.view){ D.abort='no View'; D.errors.push('launch row has no View'); }
if(!D.abort&&!/^[0-9a-f]{24}$/i.test(D.target)){ D.abort='invalid Target'; D.errors.push('Target "'+D.target+'" is not a plausible PlusVibe campaign id (24 hex)'); }
sd[dk]=D;
return [{json:{clientId:D.clientId||'recMISSING'}}];

const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
const r=($input.first()||{}).json||{};
const f=r.fields||r;
D.clientName=String(f['Client name']||f['Client']||'').trim();
D.ws=String(f['PlusVibe Workspace ID']||'').trim();
D.crBase=String(f['Clayroots Base ID']||'').trim();
// Shared-base link, used to build a deep link to the exact deployed view on the receipt.
D.share=String(f['Clayroots shareable link']||f['Clayroots Shareable Link']||'').trim().replace(/\/+$/,'');
if(!D.abort&&(!D.ws||!D.crBase)){ D.abort='client not deployable'; D.errors.push('client missing PlusVibe Workspace ID or Clayroots Base ID'); }
return [{json:{ws:D.ws||'none'}}];

const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
if(!D.abort){
  const camps=[];
  for(const it of $input.all()){
    const j=it.json||{};
    const arr=Array.isArray(j)?j:(Array.isArray(j.campaigns)?j.campaigns:(Array.isArray(j.data)?j.data:((j.id||j._id)?[j]:[])));
    for(const x of arr){ if(x&&(x.id||x._id)) camps.push(x); }
  }
  const hit=camps.find(x=>String(x.id||x._id)===D.target);
  if(!hit){ D.abort='campaign not found'; D.errors.push('campaign '+D.target+' not found in workspace '+D.ws+' ('+camps.length+' campaigns listed); nothing was sent'); }
  else { D.campName=hit.camp_name||hit.name||D.target; }
}
return [{json:{abort:!!D.abort, crBase:D.crBase||'', target:D.target||'', metaUrl:'https://api.airtable.com/v0/meta/bases/'+(D.crBase||'missing')+'/tables'}}];

const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
if(D.abort){ return [{json:{needDe:false, view:D.view, crBase:D.crBase, tableId:D.tableId, dncTableId:''}}]; }
const tables=D.schemaTables||[];
const t=tables.find(x=>x.id===D.tableId);
if(!t){ D.abort='table not found'; D.errors.push('table '+D.tableId+' not resolved in schema'); return [{json:{needDe:false, view:D.view, crBase:D.crBase, tableId:D.tableId, dncTableId:''}}]; }
const dncT=tables.find(x=>String(x.name).toLowerCase()==='dnc');
D.dncTableId=dncT?dncT.id:'';
const vm=D.viewMeta||{};
const visible=Array.isArray(vm.visibleFieldIds)?vm.visibleFieldIds:null;
// THE RULE: anything VISIBLE in the view must be filled, or the row is skipped.
// IGNORE never blocks. IDENTITY is checked separately as a hard requirement.
// CORE_LEAD is sent to PlusVibe as a standard lead field, and is required when visible.
const IGNORE=new Set(['last_name','Title','Social','Phone','MX Provider','MX provider','MX']);
const IDENTITY=new Set(['Final Email','first_name','first_name_he','company_clean','Company']);
const CORE_LEAD=new Set(['State','State Full','City','Country']);
const MACHINE=new Set(['Status','MV','MV P0','MV P1','MV P2','MV P3','BB','P1','P2','P3','P1 (Trykitt)','P2 (LeadMagic)','P3 (Prospeo)','Source','Contact Source','Run ID','Build Date','Contact Key','Created','Seniority Rank','segment','query_name','ingested_at','RankInCompany','Co Rank','Campaign Segment','reloaded_patch','manually_approved','public_emails_clean','Email','Domain','Campaigns','Messages Sent','Last Contacted','Campaign Status','Bounce Reason','Synced At','Deploy Error','Name','Valid']);
const snake=k=>String(k).replace(/[^a-zA-Z0-9]+/g,'_').replace(/^_+|_+$/g,'').toLowerCase();
const fields=t.fields||[];
let hasDe=false;
for(const f of fields){ if(f.name==='Deploy Error') hasDe=true; }
const varCols=[]; const requiredCore=[];
const consider=(name)=>{
  if(MACHINE.has(name)||IGNORE.has(name)||IDENTITY.has(name)) return;
  if(CORE_LEAD.has(name)){ requiredCore.push(name); return; }
  varCols.push({name:name, key:snake(name)});
};
if(visible){
  const byId={};
  for(const f of fields) byId[f.id]=f;
  for(const fid of visible){ const f=byId[fid]; if(f) consider(f.name); }
} else {
  let why='view metadata unavailable';
  if(!D.viewId) why='view "'+D.view+'" not found in table views list';
  else if(D.viewType&&D.viewType!=='grid') why='view "'+D.view+'" is type '+D.viewType+', not grid';
  else if(vm&&vm.error) why='view metadata call failed: '+JSON.stringify(vm.error).slice(0,150);
  D.warnings.push(why+'; visibility unknown, so only identity fields are enforced and no custom variables are sent');
}
D.plan={varCols};
D.requiredCore=requiredCore;
D.schemaTables=null; D.viewMeta=null;
return [{json:{needDe:!hasDe, view:D.view, crBase:D.crBase, tableId:D.tableId, dncTableId:D.dncTableId}}];

const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
const rows=[];
for(const it of $input.all()){
  const j=it.json||{};
  if(Array.isArray(j.records)) rows.push(...j.records);
  else if(j.error) D.errors.push('view read: '+JSON.stringify(j.error).slice(0,200));
}
D.viewRows=rows;
return [{json:{hasDnc:!!D.dncTableId}}];

const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
if(D.abort){ return [{json:{ready:false, abort:true}}]; }
const rowsArr=D.viewRows||[];
D.rowsTotal=rowsArr.length;
if(!rowsArr.length){ D.abort='view empty or not found'; D.errors.push('view empty or not found: "'+(D.view||'')+'"; nothing was sent'); return [{json:{ready:false, abort:true}}]; }
const dnc={};
if(D.dncTableId){
  try{
    for(const it of $('Read DNC').all()){
      const j=it.json||{};
      const recs=Array.isArray(j.records)?j.records:[];
      for(const r of recs){ const d=String((r.fields||{})['Domain']||'').toLowerCase().trim(); if(d) dnc[d]=1; }
    }
  }catch(e){}
}
const plan=D.plan||{varCols:[]};
const requiredCore=D.requiredCore||[];
const emailRe=/^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/;
const val=v=>{ if(v===null||v===undefined) return ''; if(typeof v==='string') return v.trim(); if(typeof v==='number'||typeof v==='boolean') return String(v); if(Array.isArray(v)) return v.filter(x=>typeof x==='string'||typeof x==='number').join(', '); if(typeof v==='object'&&typeof v.value==='string') return v.value.trim(); return ''; };
// A usable first name starts with a letter and has at least two letters, in any language.
const NAME_OK=(s)=>{ const v=String(s||'').trim(); if(!v) return false; if(v.indexOf('�')>=0) return false; if(!/^\p{L}/u.test(v)) return false; return (v.match(/\p{L}/gu)||[]).length>=2; };
D.rows={}; D.emailToRow={}; D.varMisses={};
const leads=[];
for(const r of rowsArr){
  const f=r.fields||{};
  const email=String(f['Final Email']||'').trim();
  const rec={email:email.toLowerCase(), skip:null};
  D.rows[r.id]=rec;
  if(!email){ rec.skip='missing Final Email'; continue; }
  if(!emailRe.test(email)){ rec.skip='invalid email syntax'; continue; }
  const dom=String(f['Domain']||email.split('@')[1]||'').toLowerCase().trim();
  if(dom&&dnc[dom]){ rec.skip='DNC: '+dom; continue; }
  const fn=val(f['first_name']);
  const fnHe=val(f['first_name_he']);
  if(!fn&&!fnHe){ rec.skip='missing first name'; continue; }
  if(!NAME_OK(fn)&&!NAME_OK(fnHe)){ rec.skip='unusable first name: '+String(fn||fnHe).slice(0,40); continue; }
  const comp=val(f['company_clean'])||val(f['Company']);
  if(!comp){ rec.skip='missing company name'; continue; }
  // Visible standard fields must be filled too.
  let coreMiss='';
  for(const c of requiredCore){ if(!val(f[c])){ coreMiss=c; break; } }
  if(coreMiss){ D.varMisses[coreMiss]=(D.varMisses[coreMiss]||0)+1; rec.skip='missing '+coreMiss; continue; }
  const lead={email:email};
  const core={first_name:fn, last_name:val(f['last_name']), company_name:comp, state:val(f['State Full'])||val(f['State']), city:val(f['City']), country:val(f['Country']), job_title:val(f['Title'])};
  const soc=val(f['Social']);
  if(/^https?:\/\//i.test(soc)) core.linkedin_person_url=soc;
  for(const k of Object.keys(core)){ if(core[k]) lead[k]=core[k]; }
  const cv={}; const missVars=[];
  for(const col of plan.varCols){ const v=val(f[col.name]); if(v) cv[col.key]=v.slice(0,2000); else missVars.push(col.name); }
  if(missVars.length){ for(const m of missVars){ D.varMisses[m]=(D.varMisses[m]||0)+1; } rec.skip='missing '+missVars.join(', ').slice(0,120); continue; }
  if(Object.keys(cv).length) lead.custom_variables=cv;
  D.emailToRow[email.toLowerCase()]=r.id;
  leads.push(lead);
}
D.viewRows=null;
const chunks=[];
for(let i=0;i<leads.length;i+=200) chunks.push(leads.slice(i,i+200));
D.send={queue:chunks, idx:0, attempts:0};
const flagMap={'Standard':{skip_lead_in_active_pause_camp:true},'Strict':{skip_if_in_workspace:true},'Active-only':{skip_lead_for_active_only_camp:true},'None':{}};
D.flags=Object.assign({is_overwrite:true}, flagMap[D.dedupe]||flagMap['Strict']);
if(!chunks.length) return [{json:{ready:false, abort:false}}];
return [{json:{ready:true, abort:false, body:Object.assign({workspace_id:D.ws, campaign_id:D.target, leads:chunks[0]}, D.flags), wait:0}}];

const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk]; const S=D.send;
const j=($input.first()||{}).json||{};
const hasWrap=Object.prototype.hasOwnProperty.call(j,'body');
const rb=hasWrap?j.body:j;
const status=Number(j.statusCode||0);
const fmt=v=>Number(v||0).toLocaleString('en-US');
// Live progress written to the launch row after every chunk (Stamp Progress hangs off this output as a side branch; it must NEVER sit between this node and Send Done?, its Airtable output would destroy the loop state).
const emit=(o)=>{ const P=D.pv||{}; const total=S.queue.length||1; const doneChunks=Math.min(S.idx,total);
  const lines=['**Uploading to '+(D.campName||'?')+'**','','- Chunk '+fmt(doneChunks)+' of '+fmt(total),'- Sent so far: '+fmt(P.sent),'- Accepted so far: '+fmt(P.uploaded)];
  if(P.skipped) lines.push('- Already in the workspace, blocked by dedupe: '+fmt(P.skipped));
  if(P.duplicate) lines.push('- Same email twice in the upload: '+fmt(P.duplicate));
  lines.push('','Read-back and the full report follow once uploading finishes.');
  return [{json:Object.assign({_lid:D.launchId||'', _prog:lines.join('\n')}, o)}]; };
const mkBody=(chunk)=>Object.assign({workspace_id:D.ws, campaign_id:D.target, leads:chunk}, D.flags||{});
const advance=()=>{ if(S.idx<S.queue.length){ S.queue[S.idx]=null; } S.idx++; S.attempts=0; if(S.idx<S.queue.length&&S.queue[S.idx]) return emit({body:mkBody(S.queue[S.idx]), wait:2}); return emit({done:true, wait:0}); };
if(j.error&&!hasWrap&&!status){
  // The HTTP node itself errored (no request went out). Retry the same chunk, capped.
  S.attempts++;
  if(S.attempts<=3&&S.queue[S.idx]) return emit({body:mkBody(S.queue[S.idx]), wait:Math.pow(2,S.attempts)});
  D.errors.push('lead/add chunk '+(S.idx+1)+'/'+S.queue.length+' node error: '+String(j.error).slice(0,200));
  return advance();
}
const cur=S.queue[S.idx]||[];
const ok=status>=200&&status<300&&rb&&typeof rb==='object'&&!Array.isArray(rb);
if(ok){
  D.pv=D.pv||{sent:0,uploaded:0,duplicate:0,already:0,invalid:0,skipped:0,overwritten:0,overflowed:0,remaining:null};
  const P=D.pv;
  const num=(v)=>{ const n=Number(v); return Number.isFinite(n)?n:0; };
  P.sent+=num(rb.totalsent!==undefined?rb.totalsent:rb.total_sent);
  const up=num(rb.leadsuploaded!==undefined?rb.leadsuploaded:(rb.leads_uploaded!==undefined?rb.leads_uploaded:rb.uploaded_count));
  P.uploaded+=up;
  P.duplicate+=num(rb.duplicateemailcount!==undefined?rb.duplicateemailcount:rb.duplicate_email_count);
  P.already+=num(rb.alreadyincampaign!==undefined?rb.alreadyincampaign:rb.already_in_campaign);
  P.invalid+=num(rb.invalidemailcount!==undefined?rb.invalidemailcount:rb.invalid_email_count);
  P.skipped+=num(rb.skipped);
  P.overwritten+=num(rb.overwritten);
  P.overflowed+=num(rb.overflowedleadcount!==undefined?rb.overflowedleadcount:rb.overflowed_lead_count);
  const rem=rb.remaininginplan!==undefined?rb.remaininginplan:rb.remaining_in_plan;
  if(rem!==undefined&&rem!==null&&Number.isFinite(Number(rem))) P.remaining=Number(rem);
  D.uploadedNew+=up;
  return advance();
}
let idxs=[];
if(rb&&Array.isArray(rb.invalid_indexes)) idxs=rb.invalid_indexes.filter(Number.isFinite);
else if(rb&&Array.isArray(rb.errors)) idxs=rb.errors.map(e=>(e&&(e.index!==undefined?e.index:e.lead_index))).filter(Number.isFinite);
if(status===400&&idxs.length){
  const bad=new Set(idxs);
  const keep=[];
  cur.forEach((l,i)=>{
    if(bad.has(i)){
      D.errors.push('lead rejected by PV validation, dropped: '+((l&&l.email)||('index '+i)));
      const rid=D.emailToRow[String((l&&l.email)||'').toLowerCase()];
      if(rid&&D.rows[rid]&&!D.rows[rid].skip) D.rows[rid].skip='rejected by PV validation';
    } else keep.push(l);
  });
  if(keep.length){ S.queue[S.idx]=keep; return emit({body:mkBody(keep), wait:2}); }
  return advance();
}
const bs=JSON.stringify(rb||{}).toLowerCase();
if((status===413||status===400)&&cur.length>25&&/too large|payload|entity|body size|request size/.test(bs)){
  const half=Math.ceil(cur.length/2);
  const a=cur.slice(0,half), b=cur.slice(half);
  S.queue.splice(S.idx,1,a,b);
  return emit({body:mkBody(a), wait:2});
}
S.attempts++;
if(S.attempts<=3&&cur.length) return emit({body:mkBody(cur), wait:Math.pow(2,S.attempts)});
D.errors.push('lead/add chunk '+(S.idx+1)+'/'+S.queue.length+' failed after 3 retries (status '+(status||'?')+'): '+JSON.stringify(rb).slice(0,200));
return advance();

const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
D.rb={page:1, attempts:0};
return [{json:{ws:D.ws, campaign_id:D.target, page:1, wait:5}}];

const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk]; const R=D.rb;
const j=($input.first()||{}).json||{};
const hasWrap=Object.prototype.hasOwnProperty.call(j,'body');
const body=hasWrap?j.body:j;
const status=Number(j.statusCode||0);
let arr=null;
if(Array.isArray(body)) arr=body;
else if(body&&Array.isArray(body.data)) arr=body.data;
else if(body&&Array.isArray(body.leads)) arr=body.leads;
if(status&&(status<200||status>=300)) arr=null;
const emit=o=>[{json:o}];
if(arr===null){
  R.attempts++;
  if(R.attempts<=5){
    let w=Math.pow(2,R.attempts);
    const h=j.headers||{};
    const ra=Number(h['retry-after']||h['Retry-After']||0);
    if(ra>0) w=Math.max(w,Math.min(ra,120));
    return emit({ws:D.ws, campaign_id:D.target, page:R.page, wait:w});
  }
  D.rbFailed=true;
  D.errors.push('read-back failed at page '+R.page+' after 5 retries (status '+(status||'?')+'); unconfirmed rows left unstamped');
  return emit({done:true, wait:0});
}
R.attempts=0;
for(const l of arr){ const e=String(l.email||l.lead_email||'').toLowerCase().trim(); if(e) D.inCamp[e]=1; }
if(arr.length===100){
  R.page++;
  if(R.page>500){ D.rbFailed=true; D.errors.push('read-back aborted: exceeded 500 pages'); return emit({done:true, wait:0}); }
  return emit({ws:D.ws, campaign_id:D.target, page:R.page, wait:2});
}
return emit({done:true, wait:0});

const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
const patches=[];
let deployed=0, missing=0;
const skipCounts={};
for(const rid of Object.keys(D.rows||{})){
  const r=D.rows[rid];
  let v='';
  if(r.skip){ v=r.skip; const key=r.skip.indexOf('DNC:')===0?'DNC':r.skip; skipCounts[key]=(skipCounts[key]||0)+1; }
  else if(D.rbFailed){ continue; }
  else if(r.email&&D.inCamp[r.email]){ v=''; deployed++; }
  else { v='not in campaign after deploy (dedupe-skipped or PV-dropped)'; missing++; }
  patches.push({id:rid, fields:{'Deploy Error':v}});
}
D.deployed=deployed; D.missing=missing; D.skipCounts=skipCounts;
D.inCamp={}; D.emailToRow={};
const out=[];
for(let i=0;i<patches.length;i+=10) out.push({json:{crBase:D.crBase, tableId:D.tableId, body:{records:patches.slice(i,i+10), typecast:true}}});
if(!out.length) return [{json:{_none:true}}];
return out;

const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
for(const it of $input.all()){ const j=it.json||{}; if(j.error) D.errors.push('stamp write: '+JSON.stringify(j.error).slice(0,200)); }
return [{json:{stamped:true}}];

const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
let hubId='';
try{ const r=($('Find Hub Campaign').first()||{}).json||{}; if(r.id) hubId=r.id; }catch(e){}
D.receiptName=(D.tableName||D.tableId||'table')+' - '+(D.view||'view');
if(!hubId) D.warnings.push('no Hub Campaigns row for '+D.target+'; receipt created without campaign link');
// <shareable link>/<tableId>/<viewId> opens the exact view that was deployed.
let viewLink='';
if(D.share && D.tableId && D.viewId){ viewLink=D.share+'/'+D.tableId+'/'+D.viewId; }
else if(!D.share){ D.warnings.push('client has no Clayroots shareable link; receipt written without a View Link'); }
else if(!D.viewId){ D.warnings.push('view id unresolved; receipt written without a View Link'); }
D.viewLink=viewLink;
return [{json:{Name:D.receiptName, Campaign:hubId?[hubId]:[], ViewLink:viewLink}}];

const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id;
const D=sd[dk]||{errors:['deploy state missing'],warnings:[],counters:[],rows:{},skipCounts:{},launchId:''};
try{ const r=($('Create Lead List').first()||{}).json||{}; if(!r.id&&!D.abort) D.warnings.push('Lead Lists receipt creation failed'); }catch(e){ if(!D.abort) D.warnings.push('Lead Lists receipt not created'); }
const failed=D.errors||[];
const sc=D.skipCounts||{};
const skipTotal=Object.keys(sc).reduce((s,k)=>s+sc[k],0);
const fmt=v=>Number(v||0).toLocaleString('en-US');
const md=[];
md.push('**Deployed '+fmt(D.deployed||0)+' of '+fmt(D.rowsTotal||0)+' view rows to '+(D.campName||'?')+'**');
md.push('');
md.push('**Campaign:** '+(D.campName||'?')+' ('+(D.target||'?')+')');
md.push('**View:** '+(D.view||'?'));
if(D.viewLink) md.push('**Link:** '+D.viewLink);
md.push('**Dedupe mode:** '+(D.dedupe||'Strict'));
const P=D.pv;
if(P){
  md.push('');
  md.push('**Sent to PlusVibe**');
  md.push('- Sent: '+fmt(P.sent));
  md.push('- Accepted: '+fmt(P.uploaded));
  const diff=(P.sent||0)-(P.uploaded||0);
  md.push('- Not accepted: '+fmt(diff));
  if(P.skipped) md.push('   - Already in the workspace, blocked by dedupe mode "'+(D.dedupe||'Strict')+'": '+fmt(P.skipped));
  if(P.already) md.push('   - Already in this campaign: '+fmt(P.already));
  if(P.duplicate) md.push('   - Same email twice in the upload: '+fmt(P.duplicate));
  if(P.invalid) md.push('   - PlusVibe judged the email invalid: '+fmt(P.invalid));
  if(P.overflowed) md.push('   - Over your plan limit: '+fmt(P.overflowed));
  if(P.overwritten) md.push('   - Existing lead refreshed instead of added: '+fmt(P.overwritten));
  if(P.remaining!==null&&P.remaining!==undefined) md.push('- Leads left in plan: '+fmt(P.remaining));
}
if(D.missing){ md.push('- Sent but not found in the campaign afterwards: '+fmt(D.missing)); }
const vm=D.varMisses||{};
const vmKeys=Object.keys(vm).sort((a,b)=>vm[b]-vm[a]);
if(vmKeys.length){
  md.push('');
  md.push('**Not sent: a required column was empty**');
  md.push('These rows never left Airtable. Fill the column or hide it from the view.');
  for(const k of vmKeys) md.push('- '+k+' was empty on '+fmt(vm[k])+' row'+(vm[k]===1?'':'s'));
}
if(skipTotal){
  md.push('');
  md.push('**Not sent: other reasons ('+fmt(skipTotal)+')**');
  for(const k of Object.keys(sc)) md.push('- '+k+': '+fmt(sc[k]));
}
if(D.receiptName){ md.push(''); md.push('**Lead list receipt:** '+D.receiptName); }
if((D.warnings||[]).length){ md.push(''); md.push('**Warnings ('+D.warnings.length+')**'); for(const w of D.warnings) md.push('- '+w); }
